-- =====================================================================
-- Base de práctica: tracking de opinión pública (datos 100% sintéticos)
-- Motor: PostgreSQL 13+
-- Carga:  psql -d <tu_base> -f encuestas.sql
-- =====================================================================

DROP TABLE IF EXISTS respuestas, opciones, preguntas, encuestados, provincias, encuestas CASCADE;

CREATE TABLE encuestas (
    id            INTEGER PRIMARY KEY,
    nombre        TEXT NOT NULL,
    fecha_inicio  DATE NOT NULL,
    fecha_fin     DATE NOT NULL,
    modalidad     TEXT NOT NULL            -- 'IVR' u 'Online'
);

CREATE TABLE provincias (
    id      INTEGER PRIMARY KEY,
    nombre  TEXT NOT NULL UNIQUE,
    region  TEXT NOT NULL
);

CREATE TABLE encuestados (
    id           INTEGER PRIMARY KEY,
    encuesta_id  INTEGER NOT NULL REFERENCES encuestas(id),
    sexo         CHAR(1),                  -- 'F' / 'M'
    edad         INTEGER,
    provincia    TEXT,                     -- texto tal como lo cargó el sistema de campo
    completa     BOOLEAN NOT NULL,         -- TRUE si terminó el cuestionario
    ponderador   NUMERIC(8,4)              -- peso por sexo y edad
);

CREATE TABLE preguntas (
    id           INTEGER PRIMARY KEY,
    encuesta_id  INTEGER NOT NULL REFERENCES encuestas(id),
    codigo       TEXT NOT NULL,            -- mismo código en todas las olas
    texto        TEXT NOT NULL
);

CREATE TABLE opciones (
    pregunta_id  INTEGER NOT NULL REFERENCES preguntas(id),
    valor        INTEGER NOT NULL,
    etiqueta     TEXT NOT NULL,
    PRIMARY KEY (pregunta_id, valor)
);

CREATE TABLE respuestas (
    encuestado_id  INTEGER NOT NULL REFERENCES encuestados(id),
    pregunta_id    INTEGER NOT NULL REFERENCES preguntas(id),
    valor          INTEGER NOT NULL,
    registrada_en  TIMESTAMP NOT NULL
);

